use clap::{Args, Subcommand};
use serde::{Deserialize, Serialize};

use crate::wire;

#[derive(Args, Clone, Debug, Deserialize, Serialize)]
pub struct WatchOptions {
    /// Threads to suspend when an event occurs.
    #[arg(long, default_value = "thread", value_parser = ["none", "thread", "all"])]
    pub suspend: String,
    /// Only report events generated by this thread (decimal or 0x).
    #[arg(short = 't', long, value_parser = wire::number)]
    pub thread: Option<u64>,
    /// Report only the Nth matching event, once; not a number of events to collect.
    #[arg(long, value_parser = clap::value_parser!(u32).range(1..=2147483647))]
    pub count: Option<u32>,
}

#[derive(Subcommand, Clone, Debug, Deserialize, Serialize)]
pub enum Exception {
    /// Register exception events; defaults to uncaught exceptions only.
    #[command(after_help = help_text!("exception/watch"))]
    #[command(group(clap::ArgGroup::new("exception_type").required(true).args(["class", "all"])))]
    Watch {
        /// Loaded exception type's JNI signature; also matches its subtypes.
        class: Option<String>,
        /// Watch all exception types; does not change caught/uncaught selection.
        #[arg(long)]
        all: bool,
        /// Resolve class-loader ambiguity for the supplied signature.
        #[arg(long, requires = "class", conflicts_with = "all", value_parser = wire::number)]
        type_id: Option<u64>,
        /// Include caught exceptions as well as uncaught exceptions.
        #[arg(long, conflicts_with = "caught_only")]
        with_caught: bool,
        /// Watch only caught exceptions.
        #[arg(long)]
        caught_only: bool,
        #[command(flatten)]
        #[serde(flatten)]
        options: WatchOptions,
    },
    /// Clear one exception request; does not resume suspended threads.
    #[command(after_help = help_text!("exception/unwatch"))]
    Unwatch {
        /// Decimal VM request ID returned by exception watch.
        id: u32,
    },
}

#[derive(Subcommand, Clone, Debug, Deserialize, Serialize)]
pub enum ClassPrepare {
    /// Register future class preparation events without resolving a loaded type.
    #[command(after_help = help_text!("class/prepare/watch"))]
    Watch {
        /// Dot-separated class name, optionally with one leading or trailing '*'.
        #[arg(value_parser = class_pattern)]
        pattern: String,
        #[command(flatten)]
        #[serde(flatten)]
        options: WatchOptions,
    },
    /// Clear one class preparation request; does not resume suspended threads.
    #[command(after_help = help_text!("class/prepare/unwatch"))]
    Unwatch {
        /// Decimal VM request ID returned by class prepare watch.
        id: u32,
    },
}

#[derive(Subcommand, Clone, Debug, Deserialize, Serialize)]
pub enum Field {
    /// Watch field reads; writes are separate modification events.
    #[command(after_help = help_text!("field/access/index"))]
    Access {
        #[command(subcommand)]
        #[serde(flatten)]
        command: FieldWatch,
    },
    /// Watch writes to a field.
    #[command(after_help = help_text!("field/modification/index"))]
    Modification {
        #[command(subcommand)]
        #[serde(flatten)]
        command: FieldWatch,
    },
}

#[derive(Subcommand, Clone, Debug, Deserialize, Serialize)]
pub enum FieldWatch {
    /// Register events for a field declared by the specified loaded class.
    #[command(after_help = help_text!("field/watch"))]
    Watch {
        /// JNI signature of the field's declaring class.
        class: String,
        /// Declared field name; inherited fields require their declaring class.
        field: String,
        /// Resolve class-loader ambiguity for the declaring class.
        #[arg(long, value_parser = wire::number)]
        type_id: Option<u64>,
        #[command(flatten)]
        #[serde(flatten)]
        options: WatchOptions,
    },
    /// Clear one request of this field event kind; does not resume threads.
    #[command(after_help = help_text!("field/unwatch"))]
    Unwatch {
        /// Decimal VM request ID from the corresponding watch command.
        id: u32,
    },
}

fn class_pattern(value: &str) -> Result<String, String> {
    let stars = value.bytes().filter(|byte| *byte == b'*').count();

    if value.is_empty()
        || value.contains(['/', ';'])
        || stars > 1
        || (stars == 1 && !value.starts_with('*') && !value.ends_with('*'))
    {
        return Err(
            "use a dot-separated class name with at most one leading or trailing '*'".into(),
        );
    }

    Ok(value.to_owned())
}

#[cfg(test)]
mod tests {
    use clap::Parser;

    use super::*;
    use crate::cli::{Args, Command, EntryCommand};

    #[test]
    fn exception_modes_and_filter_arguments_are_explicit() {
        for (flags, expected) in [
            (vec![], (false, false)),
            (vec!["--with-caught"], (true, false)),
            (vec!["--caught-only"], (false, true)),
        ] {
            let args = Args::try_parse_from(
                ["yaya", "exception", "watch", "--all"]
                    .into_iter()
                    .chain(flags),
            )
            .unwrap();
            let EntryCommand::SessionCommand(Command::Exception {
                command:
                    Exception::Watch {
                        with_caught,
                        caught_only,
                        ..
                    },
                ..
            }) = args.command
            else {
                panic!()
            };
            assert_eq!((with_caught, caught_only), expected);
        }
        for args in [
            vec!["exception", "watch"],
            vec!["exception", "watch", "Ltest;", "--all"],
            vec!["exception", "watch", "--all", "--type-id", "1"],
            vec![
                "exception",
                "watch",
                "--all",
                "--with-caught",
                "--caught-only",
            ],
            vec!["exception", "watch", "--all", "--count", "0"],
            vec!["exception", "watch", "--all", "--count", "2147483648"],
            vec!["exception", "watch", "--all", "--suspend", "invalid"],
            vec!["field", "access", "watch", "Ltest;"],
            vec!["field", "modification", "unwatch"],
            vec!["class", "prepare", "watch", "com.*.Foo"],
        ] {
            assert!(
                Args::try_parse_from(std::iter::once("yaya").chain(args.iter().copied())).is_err(),
                "{args:?}"
            );
        }
        for pattern in ["*", "com.example.*", "*.Foo", "com.example.Foo"] {
            assert!(class_pattern(pattern).is_ok());
        }
        for pattern in ["", "**", "a*b", "*a*", "Lcom/example/Foo;"] {
            assert!(class_pattern(pattern).is_err());
        }
    }
}
